PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <http://w3.org/ns/ldst#>
SELECT ?point ?tsid ?class WHERE {
  ?zn rdfs:label "Perimeter_top_ZN_1" .
  ?point brick:hasProperty ?sensor ;
         brick:hasSubSystem ?ss ;
         brick:isPointOf ?zn .
  ?point ref:hasTimeseriesId ?tsid .
  ?point a ?class .
}

SELECT ?point ?class ?pclass WHERE {
  ?zn rdfs:label "Perimeter_top_ZN_1" .
  ?point brick:isPointOf ?zn .
  ?point a ?class .
  OPTIONAL { ?point ref:hasTimeseriesId ?pclass }
}

